/// <summary>
/// This is an event handler class for CustInvoiceJour table
/// </summary>
class METCustInvoiceJourTable_EventHandler
{
}

Method.Source:
    /// <summary>
    /// Updates the intergration status for the sales order invoice
    /// </summary>
    /// <param name="sender">CustInvoiceJour buffer</param>
    /// <param name="e"> Get CustInvoiceJour args</param>
    [
        DataEventHandler(tableStr(CustInvoiceJour), DataEventType::Inserted),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")      
    ]
    public static void CustInvoiceJour_onInserting(Common sender, DataEventArgs e)
    {
        CustInvoiceJour custInvoiceJour = sender as CustInvoiceJour;
        METCustInvoiceJour  metCustInvoiceJour;

        metCustInvoiceJour = METCustInvoiceJour::findOrCreate(custInvoiceJour.RecId);
        metCustInvoiceJour.updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
    }
